//github.com/AdamBouhmad/open-recipe-archive"},{"id":"rcp_archive_fe1cc8931b2400e584ef","schema":1,"name":"Bramborové knedlíky na jiný způsob (Potato Dumplings - Another Method)","originalName":"Bramborové knedlíky na jiný způsob (Potato Dumplings - Another Method)","category":"cat-pasta","description":"Česká Kuchyně · źródło 1904 · licencja: public-domain","photo":"","thumb":"","servings":4,"yieldAmount":null,"yieldUnit":"g","prepTime":0,"cookTime":0,"fermentTime":0,"temperature":"","bakers":false,"sections":[{"id":"arc_fe1cc8931b24_sec_1","name":"RECEPTURA","ingredients":[{"id":"arc_fe1cc8931b24_ing_1","name":"asi šest brambor prostřední velikosti","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"asi šest brambor prostřední velikosti"},{"id":"arc_fe1cc8931b24_ing_2","name":"dvě vejce","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"dvě vejce"},{"id":"arc_fe1cc8931b24_ing_3","name":"sůl","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"sůl"},{"id":"arc_fe1cc8931b24_ing_4","name":"koflík mouky","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"koflík mouky"},{"id":"arc_fe1cc8931b24_ing_5","name":"rozpálené máslo","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"rozpálené máslo"},{"id":"arc_fe1cc8931b24_ing_6","name":"osmaženou cibulkou","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"osmaženou cibulkou"}]}],"steps":[{"id":"arc_fe1cc8931b24_stp_1","text":"Dej vařit asi šest brambor prostřední velikosti."},{"id":"arc_fe1cc8931b24_stp_2","text":"Když jsou vařené, oloupej je a za horka na vale válečkem rozválej."},{"id":"arc_fe1cc8931b24_stp_3","text":"Shrň je na hromádku, přidej k nim dvě vejce, trochu soli a koflík mouky."},{"id":"arc_fe1cc8931b24_stp_4","text":"Dobře brambory s moukou smíchej a vyválej, přidej ještě trochu mouky, aby to bylo tužší a nerozvařilo se."},{"id":"arc_fe1cc8931b24_stp_5","text":"Rozkrájej těsto na 6 dílů, rukama zakulač a dej vařit do vařící slané vody s dobrým přikrytím."},{"id":"arc_fe1cc8931b24_stp_6","text":"Když se chvíli vaří, jimi zamíchej, aby se od dna vyzvedly."},{"id":"arc_fe1cc8931b24_stp_7","text":"Když jsou vařené, rozkroj na půle, polej rozpáleným máslem a osmaženom cibulkou."}],"notes":"Česká Kuchyně · źródło 1904 · licencja: public-domain","tags":["archiwum","public-domain","ceska-kuchyne","CZ","czechia","ceska-kuchyne"],"favorite":false,"favoritedAt":0,"source":"Národní domácí kuchařka česko-americká","sourceUrl":"https://archive.org/details/nrodndomc00rosi","traditional":false,"origin":"CZ","salePrice":null,"createdAt":0,"updatedAt":0,"lastOpenedAt":0,"openCount":0,"archiveCollection":"ceska-kuchyne","archiveCollectionName":"Česká kuchyně","archiveLicense":"public-domain","sourceYear":1904,"sourceAuthor":"","sourceRepository":"https://github.com/AdamBouhmad/open-recipe-archive"},{"id":"rcp_archive_e9780512b1aedaddf83d","schema":1,"name":"Chłodnik Polski (Polish Cold Soup)","originalName":"Chłodnik Polski (Polish Cold Soup)","category":"cat-zupy","description":"Kuchnia Polska · źródło 1917 · licencja: public-domain","photo":"","thumb":"","servings":4,"yieldAmount":null,"yieldUnit":"g","prepTime":0,"cookTime":0,"fermentTime":0,"temperature":"","bakers":false,"sections":[{"id":"arc_e9780512b1ae_sec_1","name":"RECEPTURA","ingredients":[{"id":"arc_e9780512b1ae_ing_1","name":"beef or veal broth","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"beef or veal broth"},{"id":"arc_e9780512b1ae_ing_2","name":"rye kvass","amount":null,"unit":"do smaku","percent":null,"flour":false,"raw":"rye kvass to taste"},{"id":"arc_e9780512b1ae_ing_3","name":"beet greens with dill","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"beet greens with dill"},{"id":"arc_e9780512b1ae_ing_4","name":"sour cream","amount":473.177,"unit":"ml","percent":null,"flour":false,"raw":"1/2 quart of sour cream"},{"id":"arc_e9780512b1ae_ing_5","name":"broth","amount":473.177,"unit":"ml","percent":null,"flour":false,"raw":"1/2 quart of broth"},{"id":"arc_e9780512b1ae_ing_6","name":"hard-boiled eggs","amount":3,"unit":"szt.","percent":null,"flour":false,"raw":"3 hard-boiled eggs"},{"id":"arc_e9780512b1ae_ing_7","name":"cucumbers cut into cubes","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"cucumbers cut into cubes"},{"id":"arc_e9780512b1ae_ing_8","name":"some crayfish tails","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"some crayfish tails"},{"id":"arc_e9780512b1ae_ing_9","name":"ice","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"ice"}]}],"steps":[{"id":"arc_e9780512b1ae_stp_1","text":"Cook a strong beef or veal broth and strain it"},{"id":"arc_e9780512b1ae_stp_2","text":"Add rye kvass until the flavor is vinegary"},{"id":"arc_e9780512b1ae_stp_3","text":"Cook some beet greens with dill separately, chop finely, and place in a bowl"},{"id":"arc_e9780512b1ae_stp_4","text":"Pour 1/2 quart of sour cream over them"},{"id":"arc_e9780512b1ae_stp_5","text":"Mix together"},{"id":"arc_e9780512b1ae_stp_6","text":"Slowly pour in 1/2 quart of broth, constantly stirring"},{"id":"arc_e9780512b1ae_stp_7","text":"Add 3 hard-boiled eggs cut into quarters, cucumbers cut into cubes, and some crayfish tails"},{"id":"arc_e9780512b1ae_stp_8","text":"Place the bowl on ice"},{"id":"arc_e9780512b1ae_stp_9","text":"When thoroughly chilled, serve on a plate with a piece of ice"},{"id":"arc_e9780512b1ae_stp_10","text":"Instead of rye kvass, you can use cucumber brine boiled briefly with broth, or sorrel juice"}],"notes":"Kuchnia Polska · źródło 1917 · licencja: public-domain","tags":["archiwum","public-domain","kuchnia-polska","PL","poland","kuchnia-polska"],"favorite":false,"favoritedAt":0,"source":"Kuchnia polsko-amerykańska","sourceUrl":"https://archive.org/details/kuchniapolskoame00kami","traditional":false,"origin":"PL","salePrice":null,"createdAt":0,"updatedAt":0,"lastOpenedAt":0,"openCount":0,"archiveCollection":"kuchnia-polska","archiveCollectionName":"Kuchnia Polska","archiveLicense":"public-domain","sourceYear":1917,"sourceAuthor":"","sourceRepository":"https://github.com/AdamBouhmad/open-recipe-archive"},{"id":"rcp_archive_7fdeb885b622cd3a56ca","schema":1,"name":"Budino di Patate (Potato Pudding)","originalName":"Budino di Patate (Potato Pudding)","category":"cat-desery","description":"La Cucina Italiana · źródło 1891 · autor: Pellegrino Artusi · licencja: public-domain","photo":"","thumb":"","servings":4,"yieldAmount":null,"yieldUnit":"g","prepTime":0,"cookTime":0,"fermentTime":0,"temperature":"","bakers":false,"sections":[{"id":"arc_7fdeb885b622_sec_1","name":"RECEPTURA","ingredients":[{"id":"arc_7fdeb885b622_ing_1","name":"Large floury potatoes, 700 grams","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"Large floury potatoes, 700 grams"},{"id":"arc_7fdeb885b622_ing_2","name":"Sugar, 150 grams","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"Sugar, 150 grams"},{"id":"arc_7fdeb885b622_ing_3","name":"Butter, 40 grams","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"Butter, 40 grams"},{"id":"arc_7fdeb885b622_ing_4","name":"Flour, 20 grams","amount":null,"unit":"opis","percent":null,"flour":true,"raw":"Flour, 20 grams"},{"id":"arc_7fdeb885b622_ing_5","name":"Milk, 2 deciliters","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"Milk, 2 deciliters"},{"id":"arc_7fdeb885b622_ing_6","name":"Eggs, 6","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"Eggs, 6"},{"id":"arc_7fdeb885b622_ing_7","name":"salt","amount":null,"unit":"szczypta","percent":null,"flour":false,"raw":"A pinch of salt"},{"id":"arc_7fdeb885b622_ing_8","name":"Cinnamon or lemon zest flavoring","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"Cinnamon or lemon zest flavoring"}]}],"steps":[{"id":"arc_7fdeb885b622_stp_1","text":"Cook the potatoes in water or steamed, peel them and pass them hot through a sieve. Put them back on the fire with the butter, flour and milk, poured in little by little, working them well with a wooden spoon; then add the sugar, salt and flavoring and let them rest until all these things are well incorporated together."},{"id":"arc_7fdeb885b622_stp_2","text":"Remove from the fire; when they are lukewarm or cold, add the yolks and then the beaten whites."},{"id":"arc_7fdeb885b622_stp_3","text":"Cook it like all the other puddings; that is in the oven or in the stove and serve it hot."}],"notes":"La Cucina Italiana · źródło 1891 · autor: Pellegrino Artusi · licencja: public-domain","tags":["archiwum","public-domain","cucina-italiana","IT","italy","cucina-italiana"],"favorite":false,"favoritedAt":0,"source":"La scienza in cucina e l'arte di mangiar bene","sourceUrl":"https://www.gutenberg.org/ebooks/59047","traditional":false,"origin":"IT","salePrice":null,"createdAt":0,"updatedAt":0,"lastOpenedAt":0,"openCount":0,"archiveCollection":"cucina-italiana","archiveCollectionName":"Cucina Italiana","archiveLicense":"public-domain","sourceYear":1891,"sourceAuthor":"Pellegrino Artusi","sourceRepository":"https://github.com/AdamBouhmad/open-recipe-archive"},{"id":"rcp_archive_dc7efff0b0190f7b1498","schema":1,"name":"Buñuelos de Pronto (Quick Fritters)","originalName":"Buñuelos de Pronto (Quick Fritters)","category":"cat-inne","description":"La Cocina Española · źródło 1894 · autor: Ángel Muro · licencja: public-domain","photo":"","thumb":"","servings":4,"yieldAmount":null,"yieldUnit":"g","prepTime":0,"cookTime":0,"fermentTime":0,"temperature":"","bakers":false,"sections":[{"id":"arc_dc7efff0b019_sec_1","name":"RECEPTURA","ingredients":[{"id":"arc_dc7efff0b019_ing_1","name":"deciliters of water","amount":2,"unit":"szt.","percent":null,"flour":false,"raw":"two deciliters of water"},{"id":"arc_dc7efff0b019_ing_2","name":"butter","amount":50,"unit":"g","percent":null,"flour":false,"raw":"50 grams of butter"},{"id":"arc_dc7efff0b019_ing_3","name":"sugar","amount":15,"unit":"g","percent":null,"flour":false,"raw":"15 grams of sugar"},{"id":"arc_dc7efff0b019_ing_4","name":"flour","amount":116,"unit":"g","percent":null,"flour":true,"raw":"116 grams of flour"},{"id":"arc_dc7efff0b019_ing_5","name":"or more eggs","amount":3,"unit":"szt.","percent":null,"flour":false,"raw":"three or more eggs"}]}],"steps":[{"id":"arc_dc7efff0b019_stp_1","text":"In a two-liter saucepan, put two deciliters of water, 50 grams of butter, and 15 grams of sugar"},{"id":"arc_dc7efff0b019_stp_2","text":"Bring to a boil and remove from heat at the first boil"},{"id":"arc_dc7efff0b019_stp_3","text":"Add 116 grams of flour and mix well with a wooden spoon"},{"id":"arc_dc7efff0b019_stp_4","text":"Return to heat for four minutes, stirring constantly with a wooden spoon to prevent the dough from sticking"},{"id":"arc_dc7efff0b019_stp_5","text":"Remove from heat"},{"id":"arc_dc7efff0b019_stp_6","text":"Break one egg into the pan and stir with the spoon"},{"id":"arc_dc7efff0b019_stp_7","text":"When well mixed, add two more eggs one at a time, mixing well after each addition"},{"id":"arc_dc7efff0b019_stp_8","text":"If the dough is too stiff, add half an egg or a whole egg as needed"},{"id":"arc_dc7efff0b019_stp_9","text":"To test the consistency, take a spoonful of dough; it should neither spread nor stick to the spoon, but rather fall by its own weight"},{"id":"arc_dc7efff0b019_stp_10","text":"When the dough is finished, sprinkle flour on the work surface"}],"notes":"La Cocina Española · źródło 1894 · autor: Ángel Muro · licencja: public-domain","tags":["archiwum","public-domain","cocina-espanola","ES","spain","cocina-espanola"],"favorite":false,"favoritedAt":0,"source":"El Practicón: tratado completo de cocina","sourceUrl":"https://archive.org/details/elpracticntrat00muro","traditional":false,"origin":"ES","salePrice":null,"createdAt":0,"updatedAt":0,"lastOpenedAt":0,"openCount":0,"archiveCollection":"cocina-espanola","archiveCollectionName":"Cocina Española","archiveLicense":"public-domain","sourceYear":1894,"sourceAuthor":"Ángel Muro","sourceRepository":"https://github.com/AdamBouhmad/open-recipe-archive"},{"id":"rcp_archive_e8608bb963754b190177","schema":1,"name":"Bisque (Crayfish Bisque)","originalName":"Bisque (Crayfish Bisque)","category":"cat-zupy","description":"La Cuisine Française · źródło 1806 · autor: A. Viard · licencja: public-domain","photo":"","thumb":"","servings":4,"yieldAmount":null,"yieldUnit":"g","prepTime":0,"cookTime":0,"fermentTime":0,"temperature":"","bakers":false,"sections":[{"id":"arc_e8608bb96375_sec_1","name":"RECEPTURA","ingredients":[{"id":"arc_e8608bb96375_ing_1","name":"crayfish, fifty","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"crayfish, fifty"},{"id":"arc_e8608bb96375_ing_2","name":"salt","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"salt"},{"id":"arc_e8608bb96375_ing_3","name":"pepper","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"pepper"},{"id":"arc_e8608bb96375_ing_4","name":"nutmeg","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"nutmeg"},{"id":"arc_e8608bb96375_ing_5","name":"butter, a quarter pound","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"butter, a quarter pound"},{"id":"arc_e8608bb96375_ing_6","name":"rice","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"rice"},{"id":"arc_e8608bb96375_ing_7","name":"broth or water","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"broth or water"},{"id":"arc_e8608bb96375_ing_8","name":"bread crusts","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"bread crusts"}]}],"steps":[{"id":"arc_e8608bb96375_stp_1","text":"You will take fifty crayfish that you will wash in eight or ten waters; you will put them in a saucepan, adding salt, coarse pepper, a little grated nutmeg and a quarter pound of butter; you will put them on a fairly hot fire; you will sauté or stir them with a spoon for a quarter hour. When your crayfish are cooked, you will let them drain, and you will remove the meat that you will pound. You must make rice burst for a quarter hour in broth or water; you will drain it and put it in the mortar with your crayfish meat; when it is all well pounded, you will put it in a saucepan, and thin it with a little soup broth that you will pass through a fine sieve; when your purée is made, you will thin it with broth so that it is neither too thick nor too clear, then you will pound the crayfish shells; when they are well pounded, you will put juice in them, or the butter in which your crayfish were cooked, and you will pass this purée through a fine sieve. It should then have a red color. You will put it in a saucepan on gentle heat; try that neither one nor the other purées boil, but that they are very hot; you will have crusts from the top of the bread, that you will put in your soup tureen, and you will pour a little extremely hot broth over your bread before serving; then, at the moment of service, you will pour your first purée over your bread, and as for the one of shells, you will pour it over your soup with a large spoon, so that it has a beautiful color. This soup is made with fat as well as lean. (See Lean Broth.)"}],"notes":"La Cuisine Française · źródło 1806 · autor: A. Viard · licencja: public-domain","tags":["archiwum","public-domain","cuisine-francaise","FR","france","cuisine-francaise"],"favorite":false,"favoritedAt":0,"source":"Le Cuisinier impérial","sourceUrl":"https://archive.org/details/lecuisinierimpe00viargoog","traditional":false,"origin":"FR","salePrice":null,"createdAt":0,"updatedAt":0,"lastOpenedAt":0,"openCount":0,"archiveCollection":"cuisine-francaise","archiveCollectionName":"Cuisine Française","archiveLicense":"public-domain","sourceYear":1806,"sourceAuthor":"A. Viard","sourceRepository":"https://github.com/AdamBouhmad/open-recipe-archive"},{"id":"rcp_archive_a07e7c7f6c7f24c2df44","schema":1,"name":"Yaki Udzura (Broiled Quail or Pigeons)","originalName":"Yaki Udzura (Broiled Quail or Pigeons)","category":"cat-warzywa","description":"The Japanese Kitchen · źródło 1914 · autor: Sara Bosse & Onoto Watanna · licencja: public-domain","photo":"","thumb":"","servings":4,"yieldAmount":null,"yieldUnit":"g","prepTime":0,"cookTime":0,"fermentTime":0,"temperature":"","bakers":false,"sections":[{"id":"arc_a07e7c7f6c7f_sec_1","name":"RECEPTURA","ingredients":[{"id":"arc_a07e7c7f6c7f_ing_1","name":"Quail or pigeons","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"Quail or pigeons"},{"id":"arc_a07e7c7f6c7f_ing_2","name":"mushrooms","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"mushrooms"},{"id":"arc_a07e7c7f6c7f_ing_3","name":"aburage (bean cheese paste) Tofu","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"aburage (bean cheese paste) Tofu"},{"id":"arc_a07e7c7f6c7f_ing_4","name":"olive oil","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"olive oil"},{"id":"arc_a07e7c7f6c7f_ing_5","name":"parsley","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"parsley"},{"id":"arc_a07e7c7f6c7f_ing_6","name":"salt","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"salt"},{"id":"arc_a07e7c7f6c7f_ing_7","name":"dry flour","amount":null,"unit":"opis","percent":null,"flour":true,"raw":"dry flour"}]}],"steps":[{"id":"arc_a07e7c7f6c7f_stp_1","text":"Prepare the quail or pigeons the day before using by washing and singeing and rubbing with salt, then put them away in cool place."},{"id":"arc_a07e7c7f6c7f_stp_2","text":"Next day take half a pound of aburage, and fry the Tofu cakes in oil."},{"id":"arc_a07e7c7f6c7f_stp_3","text":"Set in warm place to drain off the oil while toasting the birds."},{"id":"arc_a07e7c7f6c7f_stp_4","text":"Dip the birds in olive oil, then in dry flour, and toast over a red-hot fire, turning quickly until they are a crisp brown."},{"id":"arc_a07e7c7f6c7f_stp_5","text":"Place each bird, or half of a bird, if it is a pigeon, on the fried Tofu, and have some white mushrooms which have been fried in oil, placed around the birds."},{"id":"arc_a07e7c7f6c7f_stp_6","text":"Sprinkle with chopped parsley, and serve very hot."}],"notes":"The Japanese Kitchen · źródło 1914 · autor: Sara Bosse & Onoto Watanna · licencja: public-domain","tags":["archiwum","public-domain","japanese-kitchen","JP","japan","japanese-kitchen"],"favorite":false,"favoritedAt":0,"source":"Chinese-Japanese Cook Book","sourceUrl":"https://archive.org/details/chinesejapanesec00boss_0","traditional":false,"origin":"JP","salePrice":null,"createdAt":0,"updatedAt":0,"lastOpenedAt":0,"openCount":0,"archiveCollection":"japanese-kitchen","archiveCollectionName":"Japanese Kitchen","archiveLicense":"public-domain","sourceYear":1914,"sourceAuthor":"Sara Bosse & Onoto Watanna","sourceRepository":"https://github.com/AdamBouhmad/open-recipe-archive"},{"id":"rcp_archive_5dfcb675854e5217aea3","schema":1,"name":"Hard Immortal Food","originalName":"Hard Immortal Food","category":"cat-desery","description":"The Chinese Kitchen · źródło 1917 · autor: Shiu Wong Chan · licencja: public-domain","photo":"","thumb":"","servings":4,"yieldAmount":null,"yieldUnit":"g","prepTime":0,"cookTime":0,"fermentTime":0,"temperature":"","bakers":false,"sections":[{"id":"arc_5dfcb675854e_sec_1","name":"RECEPTURA","ingredients":[{"id":"arc_5dfcb675854e_ing_1","name":"pieces bean cake","amount":12,"unit":"szt.","percent":null,"flour":false,"raw":"12 pieces bean cake"},{"id":"arc_5dfcb675854e_ing_2","name":"East melon (twice the amount of bean cake)","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"East melon (twice the amount of bean cake)"},{"id":"arc_5dfcb675854e_ing_3","name":"cups white nuts","amount":2,"unit":"szt.","percent":null,"flour":false,"raw":"2 cups white nuts"}]}],"steps":[{"id":"arc_5dfcb675854e_stp_1","text":"Cut each bean cake into 4 pieces. Cut the melon into pieces 1 inch by 1 inch by 1½ inches."},{"id":"arc_5dfcb675854e_stp_2","text":"Fry all in an oiled pan."},{"id":"arc_5dfcb675854e_stp_3","text":"Add enough water to cover. Add ¼ cake of red cheese and plenty of oil. Mix. Cook for 1 hour."}],"notes":"The Chinese Kitchen · źródło 1917 · autor: Shiu Wong Chan · licencja: public-domain","tags":["archiwum","public-domain","chinese-kitchen","CN","china","chinese-kitchen"],"favorite":false,"favoritedAt":0,"source":"The Chinese Cook Book","sourceUrl":"https://archive.org/details/chinesecookbook00chan","traditional":false,"origin":"CN","salePrice":null,"createdAt":0,"updatedAt":0,"lastOpenedAt":0,"openCount":0,"archiveCollection":"chinese-kitchen","archiveCollectionName":"Chinese Kitchen","archiveLicense":"public-domain","sourceYear":1917,"sourceAuthor":"Shiu Wong Chan","sourceRepository":"https://github.com/AdamBouhmad/open-recipe-archive"},{"id":"rcp_archive_e2dfd327157caf9c33d1","schema":1,"name":"Bavarian Cream with Liqueur","originalName":"Bavarian Cream with Liqueur","category":"cat-cocktaile","description":"The Indian Kitchen · źródło 1885 · autor: Wyvern (A.R. Kenney-Herbert) · licencja: public-domain","photo":"","thumb":"","servings":4,"yieldAmount":null,"yieldUnit":"g","prepTime":0,"cookTime":0,"fermentTime":0,"temperature":"","bakers":false,"sections":[{"id":"arc_e2dfd327157c_sec_1","name":"RECEPTURA","ingredients":[{"id":"arc_e2dfd327157c_ing_1","name":"-quarters of an ounce of gelatine","amount":3,"unit":"szt.","percent":null,"flour":false,"raw":"three-quarters of an ounce of gelatine"},{"id":"arc_e2dfd327157c_ing_2","name":"half a liqueur-glass of brandy or sherry","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"half a liqueur-glass of brandy or sherry"},{"id":"arc_e2dfd327157c_ing_3","name":"a few drops of vanilla essence","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"a few drops of vanilla essence"},{"id":"arc_e2dfd327157c_ing_4","name":"cocoa powder","amount":28.35,"unit":"g","percent":null,"flour":false,"raw":"one ounce of cocoa powder"},{"id":"arc_e2dfd327157c_ing_5","name":"boiling milk","amount":473.176,"unit":"ml","percent":null,"flour":false,"raw":"one pint of boiling milk"},{"id":"arc_e2dfd327157c_ing_6","name":"sugar","amount":56.7,"unit":"g","percent":null,"flour":false,"raw":"two ounces of sugar"},{"id":"arc_e2dfd327157c_ing_7","name":"yolks of eight eggs","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"yolks of eight eggs"},{"id":"arc_e2dfd327157c_ing_8","name":"dissolved gelatine","amount":28.35,"unit":"g","percent":null,"flour":false,"raw":"one ounce of dissolved gelatine"},{"id":"arc_e2dfd327157c_ing_9","name":"coffee-cupful of whipped cream","amount":1,"unit":"szt.","percent":null,"flour":false,"raw":"one coffee-cupful of whipped cream"}]}],"steps":[{"id":"arc_e2dfd327157c_stp_1","text":"Melt three-quarters of an ounce of gelatine in a stew-pan over the fire, with half a liqueur-glass of brandy or sherry, and a few drops of vanilla essence"},{"id":"arc_e2dfd327157c_stp_2","text":"Strain it through a tamis cloth, till clear, and set it to get cool"},{"id":"arc_e2dfd327157c_stp_3","text":"Take one ounce of cocoa powder, and stir it into a pint of boiling milk, adding two ounces of sugar"},{"id":"arc_e2dfd327157c_stp_4","text":"When thoroughly mixed, strain the milk through a piece of muslin"},{"id":"arc_e2dfd327157c_stp_5","text":"Let it get quite cold, and then add to it the strained yolks of eight eggs, making therewith a rich custard"},{"id":"arc_e2dfd327157c_stp_6","text":"Set the custard upon ice, having stirred an ounce of dissolved gelatine into it"},{"id":"arc_e2dfd327157c_stp_7","text":"When it begins to set, add a coffee-cupful of whipped cream, mix thoroughly"},{"id":"arc_e2dfd327157c_stp_8","text":"Place a mould on ice and pour into it a layer of the vanilla jelly half an inch thick"},{"id":"arc_e2dfd327157c_stp_9","text":"When set, pour in about an inch of the cream, then a layer of jelly when the cream has set, and so on until the mould is filled"},{"id":"arc_e2dfd327157c_stp_10","text":"Serve after it has rested on ice for an hour"}],"notes":"The Indian Kitchen · źródło 1885 · autor: Wyvern (A.R. Kenney-Herbert) · licencja: public-domain","tags":["archiwum","public-domain","indian-kitchen","IN","india","indian-kitchen"],"favorite":false,"favoritedAt":0,"source":"Culinary Jottings for Madras","sourceUrl":"https://archive.org/details/culinaryjottings00kenn","traditional":false,"origin":"IN","salePrice":null,"createdAt":0,"updatedAt":0,"lastOpenedAt":0,"openCount":0,"archiveCollection":"indian-kitchen","archiveCollectionName":"Indian Kitchen","archiveLicense":"public-domain","sourceYear":1885,"sourceAuthor":"Wyvern (A.R. Kenney-Herbert)","sourceRepository":"https://github.com/AdamBouhmad/open-recipe-archive"},{"id":"rcp_archive_5ac4e485d4d811027b66","schema":1,"name":"Blinde Chokoladesuppe (Blind Chocolate Soup)","originalName":"Blinde Chokoladesuppe (Blind Chocolate Soup)","category":"cat-zupy","description":"Die Deutsche Küche · źródło 1858 · autor: Viktorine Schiller · licencja: public-domain","photo":"","thumb":"","servings":4,"yieldAmount":null,"yieldUnit":"g","prepTime":0,"cookTime":0,"fermentTime":0,"temperature":"","bakers":false,"sections":[{"id":"arc_5ac4e485d4d8_sec_1","name":"RECEPTURA","ingredients":[{"id":"arc_5ac4e485d4d8_ing_1","name":"butter","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"butter"},{"id":"arc_5ac4e485d4d8_ing_2","name":"spoons flour","amount":2,"unit":"szt.","percent":null,"flour":true,"raw":"2 spoons flour"},{"id":"arc_5ac4e485d4d8_ing_3","name":"good milk","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"good milk"}]}],"steps":[{"id":"arc_5ac4e485d4d8_stp_1","text":"Put a piece of butter in a casserole"},{"id":"arc_5ac4e485d4d8_stp_2","text":"Toast 2 spoons of flour light yellow in it"},{"id":"arc_5ac4e485d4d8_stp_3","text":"Stir it smooth with good milk"},{"id":"arc_5ac4e485d4d8_stp_4","text":"Pour in more milk as needed"}],"notes":"Die Deutsche Küche · źródło 1858 · autor: Viktorine Schiller · licencja: public-domain","tags":["archiwum","public-domain","german-kitchen","DE","germany","german-kitchen"],"favorite":false,"favoritedAt":0,"source":"Neuestes Süddeutsches Kochbuch","sourceUrl":"https://www.gutenberg.org/ebooks/52879","traditional":false,"origin":"DE","salePrice":null,"createdAt":0,"updatedAt":0,"lastOpenedAt":0,"openCount":0,"archiveCollection":"german-kitchen","archiveCollectionName":"German Kitchen","archiveLicense":"public-domain","sourceYear":1858,"sourceAuthor":"Viktorine Schiller","sourceRepository":"https://github.com/AdamBouhmad/open-recipe-archive"},{"id":"rcp_archive_4d17b6678c179738122e","schema":1,"name":"Bramborové Škubánky na Jiný Způsob (Potato Mush, Another Way)","originalName":"Bramborové Škubánky na Jiný Způsob (Potato Mush, Another Way)","category":"cat-warzywa","description":"Česká Kuchyně · źródło 1904 · licencja: public-domain","photo":"","thumb":"","servings":4,"yieldAmount":null,"yieldUnit":"g","prepTime":0,"cookTime":0,"fermentTime":0,"temperature":"","bakers":false,"sections":[{"id":"arc_4d17b6678c17_sec_1","name":"RECEPTURA","ingredients":[{"id":"arc_4d17b6678c17_ing_1","name":"potatoes","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"potatoes"},{"id":"arc_4d17b6678c17_ing_2","name":"flour","amount":null,"unit":"opis","percent":null,"flour":true,"raw":"flour"},{"id":"arc_4d17b6678c17_ing_3","name":"butter or lard","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"butter or lard"},{"id":"arc_4d17b6678c17_ing_4","name":"salt","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"salt"},{"id":"arc_4d17b6678c17_ing_5","name":"poppy seeds","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"poppy seeds"},{"id":"arc_4d17b6678c17_ing_6","name":"sugar","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"sugar"},{"id":"arc_4d17b6678c17_ing_7","name":"cheese","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"cheese"},{"id":"arc_4d17b6678c17_ing_8","name":"milk","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"milk"}]}],"steps":[{"id":"arc_4d17b6678c17_stp_1","text":"Wash and scrape nice potatoes, cut them into larger pieces, place in cold water, wash them well and cook"},{"id":"arc_4d17b6678c17_stp_2","text":"When they are soft, drain half the water, using an inverted masher poke dense holes from top to bottom"},{"id":"arc_4d17b6678c17_stp_3","text":"Pour two cupfuls of white flour into these holes; poke a bit more with the masher and let it cook, but be careful it does not burn"},{"id":"arc_4d17b6678c17_stp_4","text":"After cooking for about a quarter hour, salt it and mix well with the masher so there are no lumps and add a spoonful of butter"},{"id":"arc_4d17b6678c17_stp_5","text":"Dip a spoon in hot melted butter or lard, take the mush piece by piece and place it on a plate"},{"id":"arc_4d17b6678c17_stp_6","text":"Sprinkle with poppy seeds crushed with sugar or grated cheese and grease with hot melted butter or lard"},{"id":"arc_4d17b6678c17_stp_7","text":"If you want the mush finer, drain all the water as soon as the potatoes are soft, replace it with milk, but be careful it does not burn"}],"notes":"Česká Kuchyně · źródło 1904 · licencja: public-domain","tags":["archiwum","public-domain","ceska-kuchyne","CZ","czechia","ceska-kuchyne"],"favorite":false,"favoritedAt":0,"source":"Národní domácí kuchařka česko-americká","sourceUrl":"https://archive.org/details/nrodndomc00rosi","traditional":false,"origin":"CZ","salePrice":null,"createdAt":0,"updatedAt":0,"lastOpenedAt":0,"openCount":0,"archiveCollection":"ceska-kuchyne","archiveCollectionName":"Česká kuchyně","archiveLicense":"public-domain","sourceYear":1904,"sourceAuthor":"","sourceRepository":"https://github.com/AdamBouhmad/open-recipe-archive"},{"id":"rcp_archive_ae686e13facbafebc468","schema":1,"name":"Chłodnik Różowy (Pink Beet Soup)","originalName":"Chłodnik Różowy (Pink Beet Soup)","category":"cat-zupy","description":"Kuchnia Polska · źródło 1917 · licencja: public-domain","photo":"","thumb":"","servings":4,"yieldAmount":null,"yieldUnit":"g","prepTime":0,"cookTime":0,"fermentTime":0,"temperature":"","bakers":false,"sections":[{"id":"arc_ae686e13facb_sec_1","name":"RECEPTURA","ingredients":[{"id":"arc_ae686e13facb_ing_1","name":"pickle juice from cucumbers","amount":946.353,"unit":"ml","percent":null,"flour":false,"raw":"1 quart of pickle juice from cucumbers"},{"id":"arc_ae686e13facb_ing_2","name":"water","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"water"},{"id":"arc_ae686e13facb_ing_3","name":"fresh dill, chopped","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"fresh dill, chopped"},{"id":"arc_ae686e13facb_ing_4","name":"couple of red beets","amount":1,"unit":"szt.","percent":null,"flour":false,"raw":"a couple of red beets"},{"id":"arc_ae686e13facb_ing_5","name":"pickled cucumbers","amount":2,"unit":"szt.","percent":null,"flour":false,"raw":"2 pickled cucumbers"},{"id":"arc_ae686e13facb_ing_6","name":"hard-boiled eggs","amount":3,"unit":"szt.","percent":null,"flour":false,"raw":"3 hard-boiled eggs"},{"id":"arc_ae686e13facb_ing_7","name":"several crayfish tails","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"several crayfish tails"},{"id":"arc_ae686e13facb_ing_8","name":"cup sour cream","amount":1,"unit":"szt.","percent":null,"flour":false,"raw":"1 cup sour cream"},{"id":"arc_ae686e13facb_ing_9","name":"ice","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"ice"}]}],"steps":[{"id":"arc_ae686e13facb_stp_1","text":"Take 1 quart of pickle juice from cucumbers and add water if it is too sour. Add some chopped fresh dill and bring to a boil, then remove from heat."},{"id":"arc_ae686e13facb_stp_2","text":"Separately cook a couple of red beets, peel them, cut into thin strips and add to the warm pickle juice so it takes on color and sweetness."},{"id":"arc_ae686e13facb_stp_3","text":"Peel and slice 2 pickled cucumbers into slices; cut 3 hard-boiled eggs into quarters."},{"id":"arc_ae686e13facb_stp_4","text":"Add several crayfish tails. Whip 1 cup of sour cream well."},{"id":"arc_ae686e13facb_stp_5","text":"Mix the sour cream thoroughly with the soup first, then add the cucumbers, eggs and crayfish tails and place on ice. Serve on the table when completely cooled; you can place a piece of ice on each plate."},{"id":"arc_ae686e13facb_stp_6","text":"Note: This soup can also be served hot as borscht, in which case after adding the beets bring to a boil, remove from heat, then add sour cream and other additions and do not cook further, but serve immediately on the table."}],"notes":"Kuchnia Polska · źródło 1917 · licencja: public-domain","tags":["archiwum","public-domain","kuchnia-polska","PL","poland","kuchnia-polska"],"favorite":false,"favoritedAt":0,"source":"Kuchnia polsko-amerykańska","sourceUrl":"https://archive.org/details/kuchniapolskoame00kami","traditional":false,"origin":"PL","salePrice":null,"createdAt":0,"updatedAt":0,"lastOpenedAt":0,"openCount":0,"archiveCollection":"kuchnia-polska","archiveCollectionName":"Kuchnia Polska","archiveLicense":"public-domain","sourceYear":1917,"sourceAuthor":"","sourceRepository":"https://github.com/AdamBouhmad/open-recipe-archive"},{"id":"rcp_archive_f74c4a9e4e0d8ed97254","schema":1,"name":"Budino di Ricotta (Ricotta Pudding)","originalName":"Budino di Ricotta (Ricotta Pudding)","category":"cat-desery","description":"La Cucina Italiana · źródło 1891 · autor: Pellegrino Artusi · licencja: public-domain","photo":"","thumb":"","servings":4,"yieldAmount":null,"yieldUnit":"g","prepTime":0,"cookTime":0,"fermentTime":0,"temperature":"","bakers":false,"sections":[{"id":"arc_f74c4a9e4e0d_sec_1","name":"RECEPTURA","ingredients":[{"id":"arc_f74c4a9e4e0d_ing_1","name":"Ricotta cheese, 300 grams","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"Ricotta cheese, 300 grams"},{"id":"arc_f74c4a9e4e0d_ing_2","name":"Powdered sugar, 100 grams","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"Powdered sugar, 100 grams"},{"id":"arc_f74c4a9e4e0d_ing_3","name":"Sweet almonds, 100 grams and three or four bitter almonds","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"Sweet almonds, 100 grams and three or four bitter almonds"},{"id":"arc_f74c4a9e4e0d_ing_4","name":"Eggs, 5","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"Eggs, 5"},{"id":"arc_f74c4a9e4e0d_ing_5","name":"Lemon zest flavoring","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"Lemon zest flavoring"}]}],"steps":[{"id":"arc_f74c4a9e4e0d_stp_1","text":"Blanch the almonds in hot water and pound them very finely in a mortar with one of the egg whites mentioned above. Mix them well with the ricotta, passing this first through a sieve if it was too hard or lumpy. Add the sugar and the eggs after having beaten them separately and pour the mixture into a pudding mold that you will have first greased with butter and sprinkled with breadcrumbs. Cook it in the oven or between two"}],"notes":"La Cucina Italiana · źródło 1891 · autor: Pellegrino Artusi · licencja: public-domain","tags":["archiwum","public-domain","cucina-italiana","IT","italy","cucina-italiana"],"favorite":false,"favoritedAt":0,"source":"La scienza in cucina e l'arte di mangiar bene","sourceUrl":"https://www.gutenberg.org/ebooks/59047","traditional":false,"origin":"IT","salePrice":null,"createdAt":0,"updatedAt":0,"lastOpenedAt":0,"openCount":0,"archiveCollection":"cucina-italiana","archiveCollectionName":"Cucina Italiana","archiveLicense":"public-domain","sourceYear":1891,"sourceAuthor":"Pellegrino Artusi","sourceRepository":"https://github.com/AdamBouhmad/open-recipe-archive"},{"id":"rcp_archive_9d9b13b721941a70e64e","schema":1,"name":"Buñuelos (Spanish Fritters)","originalName":"Buñuelos (Spanish Fritters)","category":"cat-inne","description":"La Cocina Española · źródło 1894 · autor: Ángel Muro · licencja: public-domain","photo":"","thumb":"","servings":4,"yieldAmount":null,"yieldUnit":"g","prepTime":0,"cookTime":0,"fermentTime":0,"temperature":"","bakers":false,"sections":[{"id":"arc_9d9b13b72194_sec_1","name":"RECEPTURA","ingredients":[{"id":"arc_9d9b13b72194_ing_1","name":"eggs","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"eggs"},{"id":"arc_9d9b13b72194_ing_2","name":"flour","amount":null,"unit":"opis","percent":null,"flour":true,"raw":"flour"},{"id":"arc_9d9b13b72194_ing_3","name":"sugar","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"sugar"},{"id":"arc_9d9b13b72194_ing_4","name":"cinnamon","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"cinnamon"},{"id":"arc_9d9b13b72194_ing_5","name":"frying fat (3 pounds)","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"frying fat (3 pounds)"},{"id":"arc_9d9b13b72194_ing_6","name":"paper strips","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"paper strips"},{"id":"arc_9d9b13b72194_ing_7","name":"confectionery or similar toppings","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"confectionery or similar toppings"}]}],"steps":[{"id":"arc_9d9b13b72194_stp_1","text":"Crack one egg into a saucepan and stir with a spoon; when well mixed, add two more eggs, one after the other; mix well, and if the paste is too hard, add half an egg or a whole egg as needed."},{"id":"arc_9d9b13b72194_stp_2","text":"To test the consistency of the paste, take a quantity the size of an egg on a spoon and let it drip. It should not spread nor remain stuck to the spoon, but should be pulled down by its own weight."},{"id":"arc_9d9b13b72194_stp_3","text":"When the dough is finished, dust the table with flour, and place a quarter of the dough on it; dust this also with flour so it does not stick to the table or hands, and cut into pieces to form balls of two and a half centimeters, which are lined up on strips of paper four centimeters wide, which will have been lightly greased with frying fat."},{"id":"arc_9d9b13b72194_stp_4","text":"Put three pounds of frying fat in a frying pan, which is tested by frying a small piece of bread that should barely quiver; place the pan beside the stove; dip the paper strip in the frying fat and remove when the fritters have separated; move with a skimmer and increase the heat of the frying fat by gradually moving the pan to the fire until it is completely over the stove."},{"id":"arc_9d9b13b72194_stp_5","text":"When the fritters are golden and dry, drain them on a clean kitchen cloth, dust with sugar and arrange in a pyramid on a platter over a folded napkin."}],"notes":"La Cocina Española · źródło 1894 · autor: Ángel Muro · licencja: public-domain","tags":["archiwum","public-domain","cocina-espanola","ES","spain","cocina-espanola"],"favorite":false,"favoritedAt":0,"source":"El Practicón: tratado completo de cocina","sourceUrl":"https://archive.org/details/elpracticntrat00muro","traditional":false,"origin":"ES","salePrice":null,"createdAt":0,"updatedAt":0,"lastOpenedAt":0,"openCount":0,"archiveCollection":"cocina-espanola","archiveCollectionName":"Cocina Española","archiveLicense":"public-domain","sourceYear":1894,"sourceAuthor":"Ángel Muro","sourceRepository":"https://github.com/AdamBouhmad/open-recipe-archive"},{"id":"rcp_archive_af0a7c6801daa5465db4","schema":1,"name":"Blanc (Blanc Sauce)","originalName":"Blanc (Blanc Sauce)","category":"cat-sosy","description":"La Cuisine Française · źródło 1806 · autor: A. Viard · licencja: public-domain","photo":"","thumb":"","servings":4,"yieldAmount":null,"yieldUnit":"g","prepTime":0,"cookTime":0,"fermentTime":0,"temperature":"","bakers":false,"sections":[{"id":"arc_af0a7c6801da_sec_1","name":"RECEPTURA","ingredients":[{"id":"arc_af0a7c6801da_ing_1","name":"grated lard","amount":453.592,"unit":"g","percent":null,"flour":false,"raw":"One pound of grated lard"},{"id":"arc_af0a7c6801da_ing_2","name":"fat","amount":453.592,"unit":"g","percent":null,"flour":false,"raw":"One pound of fat"},{"id":"arc_af0a7c6801da_ing_3","name":"Half a pound of butter","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"Half a pound of butter"},{"id":"arc_af0a7c6801da_ing_4","name":"lemons, cut in slices without the white","amount":2,"unit":"szt.","percent":null,"flour":false,"raw":"Two lemons, cut in slices without the white"},{"id":"arc_af0a7c6801da_ing_5","name":"bay leaves","amount":2,"unit":"szt.","percent":null,"flour":false,"raw":"Two bay leaves"},{"id":"arc_af0a7c6801da_ing_6","name":"cloves","amount":2,"unit":"szt.","percent":null,"flour":false,"raw":"Two cloves"},{"id":"arc_af0a7c6801da_ing_7","name":"carrots, cut in dice","amount":4,"unit":"szt.","percent":null,"flour":false,"raw":"Four carrots, cut in dice"},{"id":"arc_af0a7c6801da_ing_8","name":"onions","amount":4,"unit":"szt.","percent":null,"flour":false,"raw":"Four onions"},{"id":"arc_af0a7c6801da_ing_9","name":"pot spoonful of water","amount":1,"unit":"szt.","percent":null,"flour":false,"raw":"One pot spoonful of water"}]}],"steps":[{"id":"arc_af0a7c6801da_stp_1","text":"Put one pound of grated lard, one pound of fat, half a pound of butter, two lemons cut in slices with the white removed, two bay leaves, two cloves, four carrots cut in dice, four onions, and one pot spoonful of water together"},{"id":"arc_af0a7c6801da_stp_2","text":"Boil until reduced"},{"id":"arc_af0a7c6801da_stp_3","text":"Be careful to stir your blanc and not let it stick"},{"id":"arc_af0a7c6801da_stp_4","text":"When there is no more moisture and your fat is melted, moisten it with water"},{"id":"arc_af0a7c6801da_stp_5","text":"Add clarified salt"},{"id":"arc_af0a7c6801da_stp_6","text":"Boil it"},{"id":"arc_af0a7c6801da_stp_7","text":"Skim it and use as needed"}],"notes":"La Cuisine Française · źródło 1806 · autor: A. Viard · licencja: public-domain","tags":["archiwum","public-domain","cuisine-francaise","FR","france","cuisine-francaise"],"favorite":false,"favoritedAt":0,"source":"Le Cuisinier impérial","sourceUrl":"https://archive.org/details/lecuisinierimpe00viargoog","traditional":false,"origin":"FR","salePrice":null,"createdAt":0,"updatedAt":0,"lastOpenedAt":0,"openCount":0,"archiveCollection":"cuisine-francaise","archiveCollectionName":"Cuisine Française","archiveLicense":"public-domain","sourceYear":1806,"sourceAuthor":"A. Viard","sourceRepository":"https://github.com/AdamBouhmad/open-recipe-archive"},{"id":"rcp_archive_56071b82047c2aba448b","schema":1,"name":"Yaki Zakana (Fried Fish)","originalName":"Yaki Zakana (Fried Fish)","category":"cat-ryby","description":"The Japanese Kitchen · źródło 1914 · autor: Sara Bosse & Onoto Watanna · licencja: public-domain","photo":"","thumb":"","servings":4,"yieldAmount":null,"yieldUnit":"g","prepTime":0,"cookTime":0,"fermentTime":0,"temperature":"","bakers":false,"sections":[{"id":"arc_56071b82047c_sec_1","name":"RECEPTURA","ingredients":[{"id":"arc_56071b82047c_ing_1","name":"small fish","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"small fish"},{"id":"arc_56071b82047c_ing_2","name":"salt","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"salt"},{"id":"arc_56071b82047c_ing_3","name":"peanut or goma-seed oil, or olive oil","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"peanut or goma-seed oil, or olive oil"},{"id":"arc_56071b82047c_ing_4","name":"oil-fried Tofu","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"oil-fried Tofu"},{"id":"arc_56071b82047c_ing_5","name":"lemon peel","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"lemon peel"}]}],"steps":[{"id":"arc_56071b82047c_stp_1","text":"Wash the fish and scale it if necessary, removing all fins."},{"id":"arc_56071b82047c_stp_2","text":"Rub well with salt."},{"id":"arc_56071b82047c_stp_3","text":"Have ready a deep iron pot and use peanut or goma-seed oil, or, if preferred, olive oil."},{"id":"arc_56071b82047c_stp_4","text":"Do not have too much oil in pan, but only enough to prevent burning."},{"id":"arc_56071b82047c_stp_5","text":"Lay the fish in the pan, but do not crowd one on top of another; fry a light brown, being careful in turning not to break the fish."},{"id":"arc_56071b82047c_stp_6","text":"Have ready oil-fried Tofu, and place each fish on a cake of about the length of the fish."},{"id":"arc_56071b82047c_stp_7","text":"Sprinkle with grated lemon peel, and serve with rice, very hot."}],"notes":"The Japanese Kitchen · źródło 1914 · autor: Sara Bosse & Onoto Watanna · licencja: public-domain","tags":["archiwum","public-domain","japanese-kitchen","JP","japan","japanese-kitchen"],"favorite":false,"favoritedAt":0,"source":"Chinese-Japanese Cook Book","sourceUrl":"https://archive.org/details/chinesejapanesec00boss_0","traditional":false,"origin":"JP","salePrice":null,"createdAt":0,"updatedAt":0,"lastOpenedAt":0,"openCount":0,"archiveCollection":"japanese-kitchen","archiveCollectionName":"Japanese Kitchen","archiveLicense":"public-domain","sourceYear":1914,"sourceAuthor":"Sara Bosse & Onoto Watanna","sourceRepository":"https://github.com/AdamBouhmad/open-recipe-archive"},{"id":"rcp_archive_b88d90b0f7946a43e56b","schema":1,"name":"Hot Water Fish","originalName":"Hot Water Fish","category":"cat-ryby","description":"The Chinese Kitchen · źródło 1917 · autor: Shiu Wong Chan · licencja: public-domain","photo":"","thumb":"","servings":4,"yieldAmount":null,"yieldUnit":"g","prepTime":0,"cookTime":0,"fermentTime":0,"temperature":"","bakers":false,"sections":[{"id":"arc_b88d90b0f794_sec_1","name":"RECEPTURA","ingredients":[{"id":"arc_b88d90b0f794_ing_1","name":"pounds cod","amount":10,"unit":"szt.","percent":null,"flour":false,"raw":"10 pounds cod"},{"id":"arc_b88d90b0f794_ing_2","name":"can Chinese Chow Chow","amount":1,"unit":"szt.","percent":null,"flour":false,"raw":"1 can Chinese Chow Chow"},{"id":"arc_b88d90b0f794_ing_3","name":"cup vinegar","amount":1,"unit":"szt.","percent":null,"flour":false,"raw":"1 cup vinegar"},{"id":"arc_b88d90b0f794_ing_4","name":"teaspoonfuls salt","amount":2,"unit":"szt.","percent":null,"flour":false,"raw":"2 teaspoonfuls salt"}]}],"steps":[{"id":"arc_b88d90b0f794_stp_1","text":"Clean the cod but do not cut it."},{"id":"arc_b88d90b0f794_stp_2","text":"Pour into a bowl, boiling water equal to 5 times the weight of the fish. Add the salt. Place the fish in this and keep covered until the water gets lukewarm."},{"id":"arc_b88d90b0f794_stp_3","text":"Put the fish on a suitable plate and pour over it the gravy made of the Chow Chow, vinegar, and a little sugar, cornstarch, and salt. Garnish with parsley and serve."}],"notes":"The Chinese Kitchen · źródło 1917 · autor: Shiu Wong Chan · licencja: public-domain","tags":["archiwum","public-domain","chinese-kitchen","CN","china","chinese-kitchen"],"favorite":false,"favoritedAt":0,"source":"The Chinese Cook Book","sourceUrl":"https://archive.org/details/chinesecookbook00chan","traditional":false,"origin":"CN","salePrice":null,"createdAt":0,"updatedAt":0,"lastOpenedAt":0,"openCount":0,"archiveCollection":"chinese-kitchen","archiveCollectionName":"Chinese Kitchen","archiveLicense":"public-domain","sourceYear":1917,"sourceAuthor":"Shiu Wong Chan","sourceRepository":"https://github.com/AdamBouhmad/open-recipe-archive"},{"id":"rcp_archive_a94c40820ba76326dbe1","schema":1,"name":"Beans","originalName":"Beans","category":"cat-warzywa","description":"The Indian Kitchen · źródło 1900 · autor: E.P. Veerasawmy · licencja: public-domain","photo":"","thumb":"","servings":4,"yieldAmount":null,"yieldUnit":"g","prepTime":0,"cookTime":0,"fermentTime":0,"temperature":"","bakers":false,"sections":[{"id":"arc_a94c40820ba7_sec_1","name":"RECEPTURA","ingredients":[{"id":"arc_a94c40820ba7_ing_1","name":"beans","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"beans"},{"id":"arc_a94c40820ba7_ing_2","name":"salt","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"salt"},{"id":"arc_a94c40820ba7_ing_3","name":"ground turmeric","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"ground turmeric"},{"id":"arc_a94c40820ba7_ing_4","name":"oil","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"oil"}]}],"steps":[{"id":"arc_a94c40820ba7_stp_1","text":"Cut the two ends and peel off the hard fibres from the two edges, if there are any."},{"id":"arc_a94c40820ba7_stp_2","text":"Boil in saline water."},{"id":"arc_a94c40820ba7_stp_3","text":"Smear ground turmeric."},{"id":"arc_a94c40820ba7_stp_4","text":"Fry with oil."}],"notes":"The Indian Kitchen · źródło 1900 · autor: E.P. Veerasawmy · licencja: public-domain","tags":["archiwum","public-domain","indian-kitchen","IN","india","indian-kitchen"],"favorite":false,"favoritedAt":0,"source":"Indian Cookery and Confectionery","sourceUrl":"https://archive.org/details/cu31924059630735","traditional":false,"origin":"IN","salePrice":null,"createdAt":0,"updatedAt":0,"lastOpenedAt":0,"openCount":0,"archiveCollection":"indian-kitchen","archiveCollectionName":"Indian Kitchen","archiveLicense":"public-domain","sourceYear":1900,"sourceAuthor":"E.P. Veerasawmy","sourceRepository":"https://github.com/AdamBouhmad/open-recipe-archive"},{"id":"rcp_archive_ee2f137b5f9d8d8bd3f4","schema":1,"name":"Blinde Punschtorte (Blind Punch Torte)","originalName":"Blinde Punschtorte (Blind Punch Torte)","category":"cat-cocktaile","description":"Die Deutsche Küche · źródło 1858 · autor: Viktorine Schiller · licencja: public-domain","photo":"","thumb":"","servings":4,"yieldAmount":null,"yieldUnit":"g","prepTime":0,"cookTime":0,"fermentTime":0,"temperature":"","bakers":false,"sections":[{"id":"arc_ee2f137b5f9d_sec_1","name":"RECEPTURA","ingredients":[{"id":"arc_ee2f137b5f9d_ing_1","name":"loth finely ground sugar","amount":6,"unit":"szt.","percent":null,"flour":false,"raw":"6 loth finely ground sugar"},{"id":"arc_ee2f137b5f9d_ing_2","name":"yolks","amount":6,"unit":"szt.","percent":null,"flour":false,"raw":"6 egg yolks"},{"id":"arc_ee2f137b5f9d_ing_3","name":"zest and juice of half a lemon","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"zest and juice of half a lemon"},{"id":"arc_ee2f137b5f9d_ing_4","name":"whites","amount":6,"unit":"szt.","percent":null,"flour":false,"raw":"6 egg whites"},{"id":"arc_ee2f137b5f9d_ing_5","name":"loth fine flour","amount":6,"unit":"szt.","percent":null,"flour":true,"raw":"6 loth fine flour"},{"id":"arc_ee2f137b5f9d_ing_6","name":"butter","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"butter"},{"id":"arc_ee2f137b5f9d_ing_7","name":"tablespoons raspberries","amount":2,"unit":"szt.","percent":null,"flour":false,"raw":"2 tablespoons raspberries"},{"id":"arc_ee2f137b5f9d_ing_8","name":"tablespoons arrack","amount":2,"unit":"szt.","percent":null,"flour":false,"raw":"2 tablespoons arrack"},{"id":"arc_ee2f137b5f9d_ing_9","name":"loth sugar","amount":4,"unit":"szt.","percent":null,"flour":false,"raw":"4 loth sugar"},{"id":"arc_ee2f137b5f9d_ing_10","name":"tablespoons cold water","amount":2,"unit":"szt.","percent":null,"flour":false,"raw":"2 tablespoons cold water"},{"id":"arc_ee2f137b5f9d_ing_11","name":"whites","amount":3,"unit":"szt.","percent":null,"flour":false,"raw":"3 egg whites"}]}],"steps":[{"id":"arc_ee2f137b5f9d_stp_1","text":"Beat 6 loth finely ground sugar with 6 egg yolks and stir together for a quarter hour"},{"id":"arc_ee2f137b5f9d_stp_2","text":"Add the zest and juice of half a lemon"},{"id":"arc_ee2f137b5f9d_stp_3","text":"Beat 6 egg whites into stiff peaks"},{"id":"arc_ee2f137b5f9d_stp_4","text":"Fold 6 loth fine flour into the mixture"},{"id":"arc_ee2f137b5f9d_stp_5","text":"Butter a baking sheet, spread one quarter of the mixture on it, and let it half-cook in the oven"},{"id":"arc_ee2f137b5f9d_stp_6","text":"Mix 2 tablespoons raspberries with 2 tablespoons arrack, remove the sheet from the oven, spread the raspberries over it, spread the remaining mixture on top, and bake completely in the oven"},{"id":"arc_ee2f137b5f9d_stp_7","text":"For the icing: cook 4 loth sugar and 2 tablespoons cold water in a brass pan until it reaches the thread stage"},{"id":"arc_ee2f137b5f9d_stp_8","text":"Beat 3 egg whites into stiff peaks, stir into the cooked sugar"},{"id":"arc_ee2f137b5f9d_stp_9","text":"Turn the torte out onto a plate, cover with the egg white icing, and smooth the surface with a knife"}],"notes":"Die Deutsche Küche · źródło 1858 · autor: Viktorine Schiller · licencja: public-domain","tags":["archiwum","public-domain","german-kitchen","DE","germany","german-kitchen"],"favorite":false,"favoritedAt":0,"source":"Neuestes Süddeutsches Kochbuch","sourceUrl":"https://www.gutenberg.org/ebooks/52879","traditional":false,"origin":"DE","salePrice":null,"createdAt":0,"updatedAt":0,"lastOpenedAt":0,"openCount":0,"archiveCollection":"german-kitchen","archiveCollectionName":"German Kitchen","archiveLicense":"public-domain","sourceYear":1858,"sourceAuthor":"Viktorine Schiller","sourceRepository":"https://github.com/AdamBouhmad/open-recipe-archive"},{"id":"rcp_archive_4413d2ddf49125a1a32d","schema":1,"name":"Bramborové Škubánky (Potato Mush)","originalName":"Bramborové Škubánky (Potato Mush)","category":"cat-warzywa","description":"Česká Kuchyně · źródło 1904 · licencja: public-domain","photo":"","thumb":"","servings":4,"yieldAmount":null,"yieldUnit":"g","prepTime":0,"cookTime":0,"fermentTime":0,"temperature":"","bakers":false,"sections":[{"id":"arc_4413d2ddf491_sec_1","name":"RECEPTURA","ingredients":[{"id":"arc_4413d2ddf491_ing_1","name":"peeled potatoes","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"peeled potatoes"},{"id":"arc_4413d2ddf491_ing_2","name":"salt","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"salt"},{"id":"arc_4413d2ddf491_ing_3","name":"flour","amount":null,"unit":"opis","percent":null,"flour":true,"raw":"flour"},{"id":"arc_4413d2ddf491_ing_4","name":"butter","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"butter"},{"id":"arc_4413d2ddf491_ing_5","name":"poppy seeds","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"poppy seeds"}]}],"steps":[{"id":"arc_4413d2ddf491_stp_1","text":"Boil about a quart of peeled potatoes, adding about half a spoonful of salt"},{"id":"arc_4413d2ddf491_stp_2","text":"When they are almost done, sprinkle an incomplete cupful of white flour on them and let them boil for about five minutes more"},{"id":"arc_4413d2ddf491_stp_3","text":"The potatoes and flour will finish cooking at the same time"},{"id":"arc_4413d2ddf491_stp_4","text":"Drain the water, salt the cooked potatoes to taste, add a piece of butter and mash everything well with a stick so that no piece of potato or lump of flour remains"},{"id":"arc_4413d2ddf491_stp_5","text":"Cut the mush with a spoon into pieces, place on a plate and sprinkle with poppy seeds and hot melted butter"}],"notes":"Česká Kuchyně · źródło 1904 · licencja: public-domain","tags":["archiwum","public-domain","ceska-kuchyne","CZ","czechia","ceska-kuchyne"],"favorite":false,"favoritedAt":0,"source":"Národní domácí kuchařka česko-americká","sourceUrl":"https://archive.org/details/nrodndomc00rosi","traditional":false,"origin":"CZ","salePrice":null,"createdAt":0,"updatedAt":0,"lastOpenedAt":0,"openCount":0,"archiveCollection":"ceska-kuchyne","archiveCollectionName":"Česká kuchyně","archiveLicense":"public-domain","sourceYear":1904,"sourceAuthor":"","sourceRepository":"https://github.com/AdamBouhmad/open-recipe-archive"},{"id":"rcp_archive_e26739f02ad5212332e2","schema":1,"name":"Chłodnik Różowy (Pink Cold Soup)","originalName":"Chłodnik Różowy (Pink Cold Soup)","category":"cat-zupy","description":"Kuchnia Polska · źródło 1917 · licencja: public-domain","photo":"","thumb":"","servings":4,"yieldAmount":null,"yieldUnit":"g","prepTime":0,"cookTime":0,"fermentTime":0,"temperature":"","bakers":false,"sections":[{"id":"arc_e26739f02ad5_sec_1","name":"RECEPTURA","ingredients":[{"id":"arc_e26739f02ad5_ing_1","name":"cucumber brine","amount":946.353,"unit":"ml","percent":null,"flour":false,"raw":"1 quart of cucumber brine"},{"id":"arc_e26739f02ad5_ing_2","name":"water (if too sour)","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"water (if too sour)"},{"id":"arc_e26739f02ad5_ing_3","name":"chopped dill","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"chopped dill"},{"id":"arc_e26739f02ad5_ing_4","name":"a few red beets","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"a few red beets"},{"id":"arc_e26739f02ad5_ing_5","name":"pickled cucumbers","amount":2,"unit":"szt.","percent":null,"flour":false,"raw":"2 pickled cucumbers"},{"id":"arc_e26739f02ad5_ing_6","name":"hard-boiled eggs","amount":3,"unit":"szt.","percent":null,"flour":false,"raw":"3 hard-boiled eggs"},{"id":"arc_e26739f02ad5_ing_7","name":"several crayfish tails","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"several crayfish tails"},{"id":"arc_e26739f02ad5_ing_8","name":"sour cream","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"sour cream"}]}],"steps":[{"id":"arc_e26739f02ad5_stp_1","text":"Take 1 quart of cucumber brine and add water if it is too sour"},{"id":"arc_e26739f02ad5_stp_2","text":"Add chopped dill and boil, then remove from heat"},{"id":"arc_e26739f02ad5_stp_3","text":"Cook a few red beets separately, peel, and cut into thin strips"},{"id":"arc_e26739f02ad5_stp_4","text":"Add to the warm brine so it absorbs color and sweetness"},{"id":"arc_e26739f02ad5_stp_5","text":"Peel and slice 2 pickled cucumbers"},{"id":"arc_e26739f02ad5_stp_6","text":"Cut 3 hard-boiled eggs into quarters"},{"id":"arc_e26739f02ad5_stp_7","text":"Add several crayfish tails"},{"id":"arc_e26739f02ad5_stp_8","text":"Beat 1 cup of sour cream well"},{"id":"arc_e26739f02ad5_stp_9","text":"Combine all ingredients"}],"notes":"Kuchnia Polska · źródło 1917 · licencja: public-domain","tags":["archiwum","public-domain","kuchnia-polska","PL","poland","kuchnia-polska"],"favorite":false,"favoritedAt":0,"source":"Kuchnia polsko-amerykańska","sourceUrl":"https://archive.org/details/kuchniapolskoame00kami","traditional":false,"origin":"PL","salePrice":null,"createdAt":0,"updatedAt":0,"lastOpenedAt":0,"openCount":0,"archiveCollection":"kuchnia-polska","archiveCollectionName":"Kuchnia Polska","archiveLicense":"public-domain","sourceYear":1917,"sourceAuthor":"","sourceRepository":"https://github.com/AdamBouhmad/open-recipe-archive"},{"id":"rcp_archive_00ffae08abcfca1d00c0","schema":1,"name":"Budino di Ricotta (Ricotta Pudding)","originalName":"Budino di Ricotta (Ricotta Pudding)","category":"cat-desery","description":"La Cucina Italiana · źródło 1891 · autor: Pellegrino Artusi · licencja: public-domain","photo":"","thumb":"","servings":4,"yieldAmount":null,"yieldUnit":"g","prepTime":0,"cookTime":0,"fermentTime":0,"temperature":"","bakers":false,"sections":[{"id":"arc_00ffae08abcf_sec_1","name":"RECEPTURA","ingredients":[{"id":"arc_00ffae08abcf_ing_1","name":"Ricotta, 300 grams","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"Ricotta, 300 grams"},{"id":"arc_00ffae08abcf_ing_2","name":"Powdered sugar, 100 grams","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"Powdered sugar, 100 grams"},{"id":"arc_00ffae08abcf_ing_3","name":"Sweet almonds, 100 grams and three or four bitter almonds","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"Sweet almonds, 100 grams and three or four bitter almonds"},{"id":"arc_00ffae08abcf_ing_4","name":"Eggs, 5","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"Eggs, 5"},{"id":"arc_00ffae08abcf_ing_5","name":"Lemon zest for flavoring","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"Lemon zest for flavoring"}]}],"steps":[{"id":"arc_00ffae08abcf_stp_1","text":"Blanch the almonds in hot water and pound them very finely in a mortar with one of the egg whites mentioned above"},{"id":"arc_00ffae08abcf_stp_2","text":"Mix them well with the ricotta, passing the ricotta first through a sieve if it were too hard or lumpy"},{"id":"arc_00ffae08abcf_stp_3","text":"Add the sugar and the eggs after having beaten them separately and pour the mixture into a pudding mold that you will have first buttered and sprinkled with breadcrumbs"},{"id":"arc_00ffae08abcf_stp_4","text":"Cook it in the oven or between two fires in a stove and serve it cold"}],"notes":"La Cucina Italiana · źródło 1891 · autor: Pellegrino Artusi · licencja: public-domain","tags":["archiwum","public-domain","cucina-italiana","IT","italy","cucina-italiana"],"favorite":false,"favoritedAt":0,"source":"La scienza in cucina e l'arte di mangiar bene","sourceUrl":"https://www.gutenberg.org/ebooks/59047","traditional":false,"origin":"IT","salePrice":null,"createdAt":0,"updatedAt":0,"lastOpenedAt":0,"openCount":0,"archiveCollection":"cucina-italiana","archiveCollectionName":"Cucina Italiana","archiveLicense":"public-domain","sourceYear":1891,"sourceAuthor":"Pellegrino Artusi","sourceRepository":"https://github.com/AdamBouhmad/open-recipe-archive"},{"id":"rcp_archive_357db0ed5637094a8829","schema":1,"name":"Cabeza de Jabalí (Wild Boar Head)","originalName":"Cabeza de Jabalí (Wild Boar Head)","category":"cat-mieso","description":"La Cocina Española · źródło 1894 · autor: Ángel Muro · licencja: public-domain","photo":"","thumb":"","servings":4,"yieldAmount":null,"yieldUnit":"g","prepTime":0,"cookTime":0,"fermentTime":0,"temperature":"","bakers":false,"sections":[{"id":"arc_357db0ed5637_sec_1","name":"RECEPTURA","ingredients":[{"id":"arc_357db0ed5637_ing_1","name":"Head of a wild boar","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"Head of a wild boar"},{"id":"arc_357db0ed5637_ing_2","name":"Salt","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"Salt"},{"id":"arc_357db0ed5637_ing_3","name":"Pepper","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"Pepper"},{"id":"arc_357db0ed5637_ing_4","name":"Nutmeg in powder","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"Nutmeg in powder"},{"id":"arc_357db0ed5637_ing_5","name":"Parsley, finely chopped","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"Parsley, finely chopped"},{"id":"arc_357db0ed5637_ing_6","name":"Chives, finely chopped","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"Chives, finely chopped"},{"id":"arc_357db0ed5637_ing_7","name":"Tongue","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"Tongue"},{"id":"arc_357db0ed5637_ing_8","name":"Brains","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"Brains"},{"id":"arc_357db0ed5637_ing_9","name":"Ears","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"Ears"},{"id":"arc_357db0ed5637_ing_10","name":"Loin of the same wild boar","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"Loin of the same wild boar"},{"id":"arc_357db0ed5637_ing_11","name":"Pork lard, melted","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"Pork lard, melted"},{"id":"arc_357db0ed5637_ing_12","name":"Toasted and sifted breadcrumbs","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"Toasted and sifted breadcrumbs"},{"id":"arc_357db0ed5637_ing_13","name":"Kitchen twine","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"Kitchen twine"},{"id":"arc_357db0ed5637_ing_14","name":"Truffle slices (optional)","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"Truffle slices (optional)"},{"id":"arc_357db0ed5637_ing_15","name":"Pistachio slices (optional)","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"Pistachio slices (optional)"}]}],"steps":[{"id":"arc_357db0ed5637_stp_1","text":"Singe and clean the head of a wild boar with great care, split it lengthwise underneath and remove all the bones without damaging the skin."},{"id":"arc_357db0ed5637_stp_2","text":"Divide into very neat strips all the edible parts: tongue, meat, brains; add the ears, cut in the same manner, and if this seems insufficient to fill the deboned head, complete the filling with a little loin from the same wild boar."},{"id":"arc_357db0ed5637_stp_3","text":"Place all these pieces in a trough, in overlapping layers, sprinkling each layer with salt, pepper, and powdered nutmeg, finely chopped parsley and chives. Leave the dish in this brine for six days in summer and at least ten days in winter."},{"id":"arc_357db0ed5637_stp_4","text":"Fill the head with everything that was in the trough and reassemble it, sewing closed the split from where the bones and edible parts were removed."},{"id":"arc_357db0ed5637_stp_5","text":"Secure the head very well with kitchen twine, taking care not to deform it or correcting any slight imperfection, and thus well tied, cook it for ten hours in plenty of water and over low heat in a spacious pot."},{"id":"arc_357db0ed5637_stp_6","text":"Once the head is cooked, remove it from the vessel and wrap it in a napkin to squeeze and compress it well with your hands so that all the cooking water drains out."},{"id":"arc_357db0ed5637_stp_7","text":"Remove the napkin and twine, place it on a platter, and with a kitchen brush give it a coat of melted pork lard, and sprinkle it with toasted, sifted, and finely ground breadcrumbs so that the grain is uniform."},{"id":"arc_357db0ed5637_stp_8","text":"Present the head at the table cold and cut it into vertical slices, beginning with the fattest part and ending with the snout."},{"id":"arc_357db0ed5637_stp_9","text":"This preparation will turn out finer if truffle slices and pistachios are added with the viands used to fill the deboned head."}],"notes":"La Cocina Española · źródło 1894 · autor: Ángel Muro · licencja: public-domain","tags":["archiwum","public-domain","cocina-espanola","ES","spain","cocina-espanola"],"favorite":false,"favoritedAt":0,"source":"El Practicón: tratado completo de cocina","sourceUrl":"https://archive.org/details/elpracticntrat00muro","traditional":false,"origin":"ES","salePrice":null,"createdAt":0,"updatedAt":0,"lastOpenedAt":0,"openCount":0,"archiveCollection":"cocina-espanola","archiveCollectionName":"Cocina Española","archiveLicense":"public-domain","sourceYear":1894,"sourceAuthor":"Ángel Muro","sourceRepository":"https://github.com/AdamBouhmad/open-recipe-archive"},{"id":"rcp_archive_7771255d0897fdf9a926","schema":1,"name":"Blanc (Blanc Sauce)","originalName":"Blanc (Blanc Sauce)","category":"cat-sosy","description":"La Cuisine Française · źródło 1806 · autor: A. Viard · licencja: public-domain","photo":"","thumb":"","servings":4,"yieldAmount":null,"yieldUnit":"g","prepTime":0,"cookTime":0,"fermentTime":0,"temperature":"","bakers":false,"sections":[{"id":"arc_7771255d0897_sec_1","name":"RECEPTURA","ingredients":[{"id":"arc_7771255d0897_ing_1","name":"fourteen ounces of beef fat, cut into dice","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"fourteen ounces of beef fat, cut into dice"},{"id":"arc_7771255d0897_ing_2","name":"grated lard","amount":453.592,"unit":"g","percent":null,"flour":false,"raw":"one pound of grated lard"},{"id":"arc_7771255d0897_ing_3","name":"half a pound of butter","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"half a pound of butter"},{"id":"arc_7771255d0897_ing_4","name":"carrots","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"carrots"},{"id":"arc_7771255d0897_ing_5","name":"onions","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"onions"},{"id":"arc_7771255d0897_ing_6","name":"thyme","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"thyme"},{"id":"arc_7771255d0897_ing_7","name":"or four bay leaves","amount":3,"unit":"szt.","percent":null,"flour":false,"raw":"three or four bay leaves"},{"id":"arc_7771255d0897_ing_8","name":"or three lemons, with the peel, seeds, and white removed","amount":2,"unit":"szt.","percent":null,"flour":false,"raw":"two or three lemons, with the peel, seeds, and white removed"},{"id":"arc_7771255d0897_ing_9","name":"water","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"water"},{"id":"arc_7771255d0897_ing_10","name":"clarified salt water","amount":null,"unit":"opis","percent":null,"flour":false,"raw":"clarified salt water"}]}],"steps":[{"id":"arc_7771255d0897_stp_1","text":"Cut the beef fat into dice, or larger depending on the size of your blanc"},{"id":"arc_7771255d0897_stp_2","text":"Cut the carrots, onions, and sliced lemons, and put them with your fat"},{"id":"arc_7771255d0897_stp_3","text":"Fill a large cooking spoon with water"},{"id":"arc_7771255d0897_stp_4","text":"Bring to a boil until the contents of your pot froth a little and your fat is melted"},{"id":"arc_7771255d0897_stp_5","text":"Stir your blanc with a wooden spoon"},{"id":"arc_7771255d0897_stp_6","text":"Do not let it take color"},{"id":"arc_7771255d0897_stp_7","text":"Moisten it with water"},{"id":"arc_7771255d0897_stp_8","text":"Add clarified salt water to season it"},{"id":"arc_7771255d0897_stp_9","text":"Let your blanc boil, skim it, and use it for the purposes indicated"}],"notes":"La Cuisine Française · źródło 1806 · autor: A. Viard · licencja: public-domain","tags":["archiwum","public-domain","cuisine-francaise","FR","france","cuisine-francaise"],"favorite":false,"favoritedAt":0,"source":"Le Cuisinier impérial","sourceUrl":"https://archive.org/details/lecuisinierimpe00viargoog","traditional":false,"origin":"FR","salePrice":null,"createdAt":0,"updatedAt":0,"lastOpenedAt":0,"openCount":0,"archiveCollection":"cuisine-francaise","archiveCollectionName":"Cuisine Française","archiveLicense":"public-domain","sourceYear":1806,"sourceAuthor":"A. Viard","sourceRepository":"https://github.com/AdamBouhmad/open-recipe-archive"},{"id":"rcp_archive_999ec3413e90df5a0c8c","schema":1,"name":"Yat Ko Main","originalName":"Yat Ko Main","category":"cat-mieso","description":"The Japanese Kitchen · źródło 1914 · autor: Sara Bosse & Onoto Watanna · licencja: public-domain","photo":"","thumb":"","servings":4,"yieldAmount":null,"yieldUnit":"g","prepTime":0,"cookTime":0,"fermentTime":0,"te